def remove_evens(nums):
    for x in nums:
        if x % 2 == 0:
            nums.remove(x)
    return nums

def build(items):
    result = []
    for x in items:
        result.insert(0, x)
    return result

def suffix_sums(nums):
    out = []
    for i in range(len(nums)):
        out.append(sum(nums[i:]))
    return out
